begin;
create temp table haircut_ids(key text primary key,id uuid);
insert into haircut_ids values('owner','b51f0000-0000-4000-8000-000000000001'),('customer','b51f0000-0000-4000-8000-000000000002'),('other','b51f0000-0000-4000-8000-000000000003'),('staff','b51f0000-0000-4000-8000-000000000004');
insert into auth.users(id,email)select id,key||'-haircut-fixture@example.invalid'from haircut_ids;
create function pg_temp.hid(k text)returns uuid language sql stable as $$select id from pg_temp.haircut_ids where key=k$$;
create function pg_temp.ok(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.denied(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=expected then return;end if;raise exception 'Expected %, got %: %',expected,sqlstate,sqlerrm;end;raise exception 'Denied operation succeeded';end;$$;
do $$begin execute format('grant usage on schema %I to anon,authenticated',pg_my_temp_schema()::regnamespace::text);end;$$;
grant all on haircut_ids to authenticated;
grant execute on function pg_temp.hid(text),pg_temp.ok(boolean,text),pg_temp.denied(text,text)to authenticated,anon;
insert into haircut_ids values('salon',gen_random_uuid()),('barber',gen_random_uuid()),('secondbarber',gen_random_uuid()),('photo',gen_random_uuid());
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.hid('owner'))::text,true);
set local role authenticated;
select public.manager_command('create_salon',jsonb_build_object('id',pg_temp.hid('salon'),'name','Haircut-only fixture','address','Akurana','opens_at','00:00','closes_at','23:59','weekdays',jsonb_build_array(0,1,2,3,4,5,6)));
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.hid('barber'),'salon_id',pg_temp.hid('salon'),'display_name','First haircut chair'));
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.hid('secondbarber'),'salon_id',pg_temp.hid('salon'),'display_name','Second haircut chair'));
select pg_temp.ok((select count(*)=0 from public.services where salon_id=pg_temp.hid('salon')),'Salon creation creates no hidden service or price');
select pg_temp.ok(jsonb_array_length(public.barber_context())=2,'Team members need no service assignments');
reset role;
insert into bookmyturn_private.salon_memberships(salon_id,user_id,role,barber_id)values(pg_temp.hid('salon'),pg_temp.hid('staff'),'barber',pg_temp.hid('secondbarber'));
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.hid('customer'))::text,true);
select public.customer_gallery('save',jsonb_build_object('id',pg_temp.hid('photo'),'title','My own reference','storage_path',pg_temp.hid('customer')||'/'||pg_temp.hid('photo')||'.jpg'));
select public.customer_gallery('save',jsonb_build_object('id',pg_temp.hid('photo'),'title','Retry','storage_path',pg_temp.hid('customer')||'/'||pg_temp.hid('photo')||'.jpg'));
select pg_temp.ok(jsonb_array_length(public.customer_gallery('list'))=1,'Photo save retries do not duplicate the gallery');
select public.customer_gallery('rename',jsonb_build_object('id',pg_temp.hid('photo'),'title','My favourite haircut'));
select pg_temp.denied($q$select public.customer_gallery('save',jsonb_build_object('storage_path',pg_temp.hid('other')||'/'||gen_random_uuid()||'.jpg'))$q$,'42501');
insert into haircut_ids select 'appointment',(public.customer_command('request_appointment',jsonb_build_object('salon_id',pg_temp.hid('salon'),'barber_id',pg_temp.hid('barber'),'starts_at',((now()at time zone 'Asia/Colombo')::date+1+'14:00'::time)at time zone 'Asia/Colombo','request_key',gen_random_uuid(),'haircut_id',pg_temp.hid('photo')))->>'id')::uuid;
select pg_temp.ok(not exists(select 1 from public.customer_slots(pg_temp.hid('salon'),null,(now()at time zone 'Asia/Colombo')::date+1,pg_temp.hid('secondbarber'))where starts_at=((now()at time zone 'Asia/Colombo')::date+1+'14:00'::time)at time zone 'Asia/Colombo'and available),'Own booked time is unavailable even with another barber');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.hid('other'))::text,true);
select pg_temp.ok(jsonb_array_length(public.customer_gallery('list'))=0,'A second customer cannot list private photos');
select pg_temp.denied($q$select public.customer_command('request_appointment',jsonb_build_object('salon_id',pg_temp.hid('salon'),'barber_id',pg_temp.hid('barber'),'starts_at',((now()at time zone 'Asia/Colombo')::date+1+'14:00'::time)at time zone 'Asia/Colombo','request_key',gen_random_uuid()))$q$,'23P01');
select pg_temp.denied($q$select public.customer_command('join_queue',jsonb_build_object('salon_id',pg_temp.hid('salon'),'request_key',gen_random_uuid(),'haircut_id',pg_temp.hid('photo')))$q$,'42501');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.hid('customer'))::text,true);
insert into haircut_ids select 'queue',(public.customer_command('join_queue',jsonb_build_object('salon_id',pg_temp.hid('salon'),'barber_id',pg_temp.hid('barber'),'present',true,'customer_name','Haircut fixture','request_key',gen_random_uuid(),'haircut_id',pg_temp.hid('photo')))->>'id')::uuid;
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.customer_state()->'queues')q where q->>'id'=pg_temp.hid('queue')::text and q->>'reference'~'^[0-9]{6}$'),'Customer sees six-digit numeric visit code');
select public.customer_gallery('remove',jsonb_build_object('id',pg_temp.hid('photo')));
select pg_temp.ok(jsonb_array_length(public.customer_gallery('list'))=0,'Removing a saved photo hides it from the gallery');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.hid('owner'))::text,true);
insert into haircut_ids select 'reference',(r->>'id')::uuid from jsonb_array_elements(public.barber_state(pg_temp.hid('barber'))->'styles')r where r->>'queue_entry_id'=pg_temp.hid('queue')::text;
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.barber_state(pg_temp.hid('barber'))->'styles')r where r->>'queue_entry_id'=pg_temp.hid('queue')::text and r->'images'->0->>'title'='My favourite haircut'),'Barber receives the optional photo even after gallery removal');
select pg_temp.ok(bookmyturn_private.haircut_media_read(pg_temp.hid('customer')||'/'||pg_temp.hid('photo')||'.jpg'),'Assigned salon owner may read the shared private image');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.hid('staff'))::text,true);
select pg_temp.ok(not bookmyturn_private.can_read_haircut(pg_temp.hid('reference')),'Staff on another chair cannot read a specific-barber reference');
select pg_temp.ok(not bookmyturn_private.haircut_media_read(pg_temp.hid('customer')||'/'||pg_temp.hid('photo')||'.jpg'),'Another chair cannot sign the private photo URL');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.hid('owner'))::text,true);
insert into haircut_ids select 'session',(public.barber_command(pg_temp.hid('barber'),'start_haircut',jsonb_build_object('id',pg_temp.hid('queue')))->>'id')::uuid;
reset role;
select pg_temp.ok(exists(select 1 from public.service_sessions where id=pg_temp.hid('session')and pricing_mode='completion'and agreed_price_minor is null and price_agreed_at is null and service_id is null),'Starting has no selected service, amount or fabricated agreement');
select pg_temp.ok(not exists(select 1 from bookmyturn_private.sales where service_session_id=pg_temp.hid('session')),'No sale is recorded before completion');
select pg_temp.ok((select count(distinct visit_code)=count(*)from(select visit_code from public.queue_entries where salon_id=pg_temp.hid('salon')union all select visit_code from public.appointments where salon_id=pg_temp.hid('salon'))v),'Active appointment and queue codes do not collide');
set local role authenticated;
select pg_temp.denied($q$select public.barber_command(pg_temp.hid('barber'),'finish_haircut',jsonb_build_object('id',pg_temp.hid('session'),'final_amount_minor',-1))$q$,'P0001');
select public.barber_command(pg_temp.hid('barber'),'finish_haircut',jsonb_build_object('id',pg_temp.hid('session'),'final_amount_minor',120000));
select public.barber_command(pg_temp.hid('barber'),'finish_haircut',jsonb_build_object('id',pg_temp.hid('session'),'final_amount_minor',120000));
reset role;
select pg_temp.ok((select count(*)=1 and min(amount_minor)=120000 from bookmyturn_private.sales where service_session_id=pg_temp.hid('session')),'Completion and retry record exactly one real sale');
select pg_temp.ok(exists(select 1 from public.service_sessions where id=pg_temp.hid('session')and final_amount_minor=120000 and final_amount_agreed_at is null),'Final amount is recorded without a fabricated customer agreement');
set local role anon;
select pg_temp.denied($q$select public.customer_gallery('list')$q$,'42501');
reset role;
select 'PASS: service-free setup/booking, private photo references, codes, chair privacy and completion-only pricing' result;
rollback;
